INSERT INTO districts (id, name, official_district, population, elderly, tourism, commerce, schools, border, neighbors, svg_path, label_x, label_y) VALUES ($sdc$sao-jose$sdc$, $sdc$São José do Imbassaí$sdc$, $sdc$1º Distrito — Sede$sdc$, 30000, 0.12, 0.16, 0.58, 0.62, 0.42, $sdc$["inoa","centro","barra"]$sdc$::jsonb, $sdc$M236,40 L442,52 L450,176 L248,188 Z$sdc$, 344, 114);
INSERT INTO districts (id, name, official_district, population, elderly, tourism, commerce, schools, border, neighbors, svg_path, label_x, label_y) VALUES ($sdc$centro$sdc$, $sdc$Centro$sdc$, $sdc$1º Distrito — Sede$sdc$, 45000, 0.15, 0.38, 0.92, 0.4, 0.28, $sdc$["sao-jose","cordeirinho","itaipuacu"]$sdc$::jsonb, $sdc$M458,44 L668,36 L680,190 L466,178 Z$sdc$, 568, 112);
INSERT INTO districts (id, name, official_district, population, elderly, tourism, commerce, schools, border, neighbors, svg_path, label_x, label_y) VALUES ($sdc$cordeirinho$sdc$, $sdc$Cordeirinho$sdc$, $sdc$2º Distrito — Ponta Negra$sdc$, 16703, 0.13, 0.22, 0.36, 0.34, 0.18, $sdc$["centro","ponta-negra"]$sdc$::jsonb, $sdc$M688,48 L912,60 L924,196 L696,184 Z$sdc$, 804, 122);
INSERT INTO districts (id, name, official_district, population, elderly, tourism, commerce, schools, border, neighbors, svg_path, label_x, label_y) VALUES ($sdc$aracatiba$sdc$, $sdc$Araçatiba$sdc$, $sdc$1º Distrito — Sede$sdc$, 15000, 0.16, 0.78, 0.48, 0.28, 0.2, $sdc$["inoa","barra"]$sdc$::jsonb, $sdc$M36,214 L228,200 L236,400 L44,412 Z$sdc$, 136, 308);
INSERT INTO districts (id, name, official_district, population, elderly, tourism, commerce, schools, border, neighbors, svg_path, label_x, label_y) VALUES ($sdc$barra$sdc$, $sdc$Barra de Maricá$sdc$, $sdc$1º Distrito — Sede$sdc$, 13000, 0.15, 0.6, 0.44, 0.26, 0.24, $sdc$["aracatiba","sao-jose","itaipuacu"]$sdc$::jsonb, $sdc$M244,206 L448,188 L456,408 L252,420 Z$sdc$, 350, 306);
INSERT INTO districts (id, name, official_district, population, elderly, tourism, commerce, schools, border, neighbors, svg_path, label_x, label_y) VALUES ($sdc$itaipuacu$sdc$, $sdc$Itaipuaçu$sdc$, $sdc$4º Distrito — Itaipuaçu$sdc$, 41000, 0.13, 0.9, 0.64, 0.38, 0.55, $sdc$["barra","centro","ponta-negra"]$sdc$::jsonb, $sdc$M464,204 L732,186 L748,416 L472,404 Z$sdc$, 604, 304);
INSERT INTO districts (id, name, official_district, population, elderly, tourism, commerce, schools, border, neighbors, svg_path, label_x, label_y) VALUES ($sdc$ponta-negra$sdc$, $sdc$Ponta Negra$sdc$, $sdc$2º Distrito — Ponta Negra$sdc$, 24000, 0.17, 0.86, 0.52, 0.3, 0.36, $sdc$["itaipuacu","cordeirinho"]$sdc$::jsonb, $sdc$M756,198 L924,210 L912,424 L740,408 Z$sdc$, 832, 308);
INSERT INTO factions (id, name, description, weight, start_value) VALUES ($sdc$comerciantes$sdc$, $sdc$Comerciantes$sdc$, $sdc$Lojistas, barraqueiros e o comércio da orla. Quarentena longa sem compensação derruba a adesão.$sdc$, 0.3, 72);
INSERT INTO factions (id, name, description, weight, start_value) VALUES ($sdc$saude$sdc$, $sdc$Profissionais de saúde$sdc$, $sdc$Equipes das UPAs e das Clínicas da Família. Lotação alta empurra a categoria para a exaustão e para a greve.$sdc$, 0.35, 74);
INSERT INTO factions (id, name, description, weight, start_value) VALUES ($sdc$civil$sdc$, $sdc$População civil$sdc$, $sdc$Moradores, incluindo grupos hesitantes diante da vacinação. O pânico e o passaporte sanitário sem diálogo reduzem a cooperação.$sdc$, 0.35, 70);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$abrir-leitos$sdc$, $sdc$Abrir leitos de campanha$sdc$, $sdc$saude$sdc$, $sdc$Amplia de forma permanente a retaguarda da rede. Não reduz a transmissão.$sdc$, $sdc$Capacidade de surto é leito, equipe e insumo. Abrir leito sem gente para trabalhar alivia pouco — por isso a contratação existe à parte.$sdc$, $sdc$instant$sdc$, 2, 0, 2, 4, NULL, $sdc${"capacity":28,"factions":{"saude":4}}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$contratar-equipes$sdc$, $sdc$Contratar e reter equipes$sdc$, $sdc$saude$sdc$, $sdc$Reforça o pessoal e reduz um pouco a letalidade de quem está internado.$sdc$, $sdc$Na superlotação, a letalidade deixa de depender só do patógeno. Equipe suficiente muda o desfecho de quem chegou ao leito.$sdc$, $sdc$instant$sdc$, 3, 0, 4, 3, NULL, $sdc${"capacity":12,"lethalityAdd":-0.003,"factions":{"saude":12}}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$triagem-idosos$sdc$, $sdc$Triagem dedicada a idosos$sdc$, $sdc$saude$sdc$, $sdc$Prioriza o grupo com maior chance de forma grave enquanto a medida estiver ativa.$sdc$, $sdc$Idade não é um detalhe demográfico. Em síndromes que ocupam leito, triagem protege quem concentra o risco.$sdc$, $sdc$sustained$sdc$, 0, 1, 0, NULL, NULL, $sdc${"elderlyRisk":-0.5,"factionsDaily":{"saude":0.8}}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$kits-protecao$sdc$, $sdc$Kits contra o toque$sdc$, $sdc$saude$sdc$, $sdc$Distribui proteção que reduz o contato útil por alguns dias.$sdc$, $sdc$A Apatia é fictícia e passa pelo toque. A medida certa depende da via de transmissão: o que segura contato não segura um mosquito.$sdc$, $sdc$instant$sdc$, 2.5, 0, 8, NULL, NULL, $sdc${"protection":0.28,"durationDays":8,"factions":{"civil":3}}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$vacinacao-bloqueio$sdc$, $sdc$Vacinação de bloqueio$sdc$, $sdc$saude$sdc$, $sdc$Sobe a cobertura de rotina. Não existe vacina contra a Apatia.$sdc$, $sdc$Vacina de rotina não cura uma doença nova. Ela impede que sarampo, pólio e outras doenças preveníveis ocupem a mesma rede no meio da crise.$sdc$, $sdc$instant$sdc$, 2.8, 0, 6, NULL, NULL, $sdc${"vaccine":10,"factions":{"saude":3,"civil":2}}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$fumigacao$sdc$, $sdc$Mutirão contra o Aedes$sdc$, $sdc$saude$sdc$, $sdc$Alivia leitos tomados por dengue e chikungunya. Não age sobre a Apatia.$sdc$, $sdc$Arboviroses competem por leito. Controlar o vetor no verão é gestão de capacidade, não confundir via de transmissão.$sdc$, $sdc$instant$sdc$, 2.2, 0, 8, NULL, NULL, $sdc${"surgeBeds":-18,"durationDays":12}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$quarentena-parcial$sdc$, $sdc$Quarentena parcial$sdc$, $sdc$fronteiras$sdc$, $sdc$Restringe parte da circulação. O comércio sente e a receita cai.$sdc$, $sdc$Quarentena, no sentido clássico, restringe quem foi exposto. Aqui a cidade usa o termo como restrição ampla de circulação — e paga o custo social disso.$sdc$, $sdc$sustained$sdc$, 0, 1.4, 0, NULL, $sdc$quarentena$sdc$, $sdc${"quarantine":0.5,"income":-0.9,"factionsDaily":{"comerciantes":-1.6,"civil":-0.3}}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$quarentena-rigida$sdc$, $sdc$Quarentena rígida$sdc$, $sdc$fronteiras$sdc$, $sdc$Corta forte o contato. Sem compensação, o comércio quebra a adesão em poucos dias.$sdc$, $sdc$Medida sanitária máxima sem pacto social dura pouco. A adesão é parte da eficácia.$sdc$, $sdc$sustained$sdc$, 0, 2.6, 0, NULL, $sdc$quarentena$sdc$, $sdc${"quarantine":0.82,"income":-1.7,"factionsDaily":{"comerciantes":-4.2,"civil":-1.5}}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$barreiras-rj106$sdc$, $sdc$Barreiras na RJ-106$sdc$, $sdc$fronteiras$sdc$, $sdc$Controla a entrada rodoviária nos bairros de passagem, sobretudo Inoã e Itaipuaçu.$sdc$, $sdc$Importação de casos segue o fluxo de pessoas. Barreira não apaga o surto local; reduz o que chega de fora.$sdc$, $sdc$sustained$sdc$, 0, 1.5, 0, NULL, NULL, $sdc${"barriers":0.75,"factionsDaily":{"comerciantes":-1.2}}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$fechar-escolas$sdc$, $sdc$Suspender aulas presenciais$sdc$, $sdc$fronteiras$sdc$, $sdc$Reduz transmissão nos bairros com mais escolas, com custo político.$sdc$, $sdc$Fechar escola é ferramenta pontual. Para o sarampo, a peça principal continua sendo a cobertura vacinal.$sdc$, $sdc$sustained$sdc$, 0, 0.8, 0, NULL, NULL, $sdc${"schoolClosure":1,"factionsDaily":{"civil":-1.1}}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$lockdown-turistico$sdc$, $sdc$Restrição da temporada$sdc$, $sdc$fronteiras$sdc$, $sdc$Segura o fluxo de visitantes na orla e reduz aglomeração turística.$sdc$, $sdc$Turismo é contato e é renda. O dilema da temporada é esse, não um vilão único.$sdc$, $sdc$sustained$sdc$, 0, 1.8, 0, NULL, NULL, $sdc${"tourism":-0.85,"factionsDaily":{"comerciantes":-3.1}}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$pesquisa-basica$sdc$, $sdc$Pesquisa básica da cura$sdc$, $sdc$pesquisa$sdc$, $sdc$Avanço lento e sustentado. Cabe junto de uma contenção moderada.$sdc$, $sdc$Vigilância e pesquisa de uma doença nova não saem do orçamento ordinário. Sem verba contínua, a cura não chega.$sdc$, $sdc$sustained$sdc$, 0, 1.4, 0, NULL, $sdc$pesquisa$sdc$, $sdc${"researchDaily":1.5}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$pesquisa-intensiva$sdc$, $sdc$Pesquisa intensiva$sdc$, $sdc$pesquisa$sdc$, $sdc$O caminho mais rápido até 100%. Consome quase toda a receita do dia.$sdc$, $sdc$Acelerar a resposta científica compete com leito, kit e compensação social. A gestão é a escolha do que não dá para fazer ao mesmo tempo.$sdc$, $sdc$sustained$sdc$, 0, 2.6, 0, NULL, $sdc$pesquisa$sdc$, $sdc${"researchDaily":2.7}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$sequenciamento$sdc$, $sdc$Sequenciar amostras$sdc$, $sdc$pesquisa$sdc$, $sdc$Um impulso único na pesquisa e melhor leitura de linhagens.$sdc$, $sdc$Vigilância genômica avisa quando a taxa de contato muda. Sem ela, a variante chega primeiro aos leitos e só depois ao boletim.$sdc$, $sdc$instant$sdc$, 2, 0, 10, NULL, NULL, $sdc${"research":5}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$campanha-publica$sdc$, $sdc$Campanha pública$sdc$, $sdc$faccoes$sdc$, $sdc$Explica a via de transmissão e recupera confiança da população e do comércio.$sdc$, $sdc$Comunicação de risco não é enfeite. Sem ela, a medida correta perde adesão e a medida errada se espalha mais rápido que o vírus.$sdc$, $sdc$instant$sdc$, 1.2, 0, 5, NULL, NULL, $sdc${"factions":{"civil":9,"comerciantes":3},"comms":1,"durationDays":4}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$combate-desinformacao$sdc$, $sdc$Combater a desinformação$sdc$, $sdc$faccoes$sdc$, $sdc$Responde à infodemia e recupera um pouco da cobertura vacinal de rotina.$sdc$, $sdc$Infodemia é excesso de informação falsa que atrapalha a resposta. Ela não substitui o vírus — abre espaço para outro.$sdc$, $sdc$instant$sdc$, 1.5, 0, 5, NULL, NULL, $sdc${"factions":{"civil":7},"vaccine":3}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$compensar-comerciantes$sdc$, $sdc$Compensar o comércio$sdc$, $sdc$faccoes$sdc$, $sdc$Auxílio pontual para sustentar a adesão à restrição de circulação.$sdc$, $sdc$Compensação não é desperdício. É o que mantém a quarentena verdadeira em vez de uma regra que ninguém cumpre.$sdc$, $sdc$instant$sdc$, 1.9, 0, 6, NULL, NULL, $sdc${"factions":{"comerciantes":16}}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$bonificar-saude$sdc$, $sdc$Adicional para as equipes$sdc$, $sdc$faccoes$sdc$, $sdc$Reduz a chance de greve quando a rede está no limite.$sdc$, $sdc$Profissional exausto é capacidade que desaparece. O adicional compra tempo; não substitui leito nem organização do fluxo.$sdc$, $sdc$instant$sdc$, 1.7, 0, 6, NULL, NULL, $sdc${"factions":{"saude":14}}$sdc$::jsonb);
INSERT INTO policies (id, name, category, summary, lesson, kind, cost, daily_cost, cooldown_days, max_uses, exclusive_group, effects) VALUES ($sdc$passaporte-sanitario$sdc$, $sdc$Passaporte sanitário$sdc$, $sdc$faccoes$sdc$, $sdc$Condiciona o acesso a espaços lotados e reduz um pouco o contato. Gera resistência.$sdc$, $sdc$Passaporte sanitário mexe em liberdade de circulação. Sem transparência, a resistência política cancela o ganho sanitário.$sdc$, $sdc$sustained$sdc$, 0, 0.9, 0, NULL, NULL, $sdc${"passport":1,"betaMult":0.9,"factionsDaily":{"civil":-3}}$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$caso-zero$sdc$, $sdc$Primeiros casos confirmados$sdc$, $sdc$Vigilância$sdc$, 1, true, $sdc$A sala de situação confirma transmissão local de Apatia, uma condição fictícia desta simulação que se espalha pelo toque. Os primeiros doentes estão no Centro, com sinal de entrada também em Itaipuaçu. Isolar casos e contatos agora reduz a taxa de contato. Só observar empurra o problema para a semana que vem.$sdc$, $sdc$Isolamento separa pessoas doentes. Quarentena restringe quem foi exposto. Os dois cortam contato. Nenhum dos dois é a mesma coisa que fechar a cidade inteira.$sdc$, NULL, NULL, NULL, NULL, false, 0, $sdc${"type":"metric","metric":"day","op":"lte","value":1}$sdc$::jsonb, $sdc$[{"id":"isolar","label":"Isolar casos e contatos próximos","outcome":"As equipes separam os doentes e pedem que os contatos fiquem em casa. A taxa de contato cai por uma semana. A verba já sente o primeiro custo.","lesson":"Começar pelo isolamento é mais barato do que deixar a prevalência subir e só então restringir a cidade toda.","effects":{"budget":-1.2,"betaAdd":-0.05,"durationDays":8,"factions":{"saude":5}}},{"id":"observar","label":"Manter só a notificação, sem isolar","outcome":"O boletim fica honesto e a ação não. Novos contatos no Centro e em Itaipuaçu entram na conta ainda esta semana.","lesson":"Vigilância sem controle informa o desastre. Ela não o impede.","effects":{"infect":{"centro":28,"itaipuacu":14},"factions":{"saude":-4}}}]$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$carnaval-marica$sdc$, $sdc$Carnaval de Maricá$sdc$, $sdc$Calendário$sdc$, 10, false, $sdc$A folia de fevereiro ocupa os quatro distritos. Os circuitos oficiais passam pela Passarela Adélia Breve, no Centro, pelo Claudinho Guimarães, em Itaipuaçu, e pelo Manhoso, em Ponta Negra. Bloco é contato prolongado. Sem medida, a transmissão por toque na orla e no comércio triplica enquanto a festa durar.$sdc$, $sdc$A taxa de contato depende do comportamento. Uma festa não muda o patógeno; muda quantas vezes as pessoas se tocam.$sdc$, 2, 2, 12, 21, false, 0, $sdc${"type":"calendar"}$sdc$::jsonb, $sdc$[{"id":"barreiras","label":"Barreiras sanitárias nos três circuitos","outcome":"A festa continua menor. Há fila, há reclamação do comércio e a aglomeração não chega a triplicar o contato.","lesson":"Reduzir densidade numa festa é controle de contato. Não é a mesma ferramenta usada contra um mosquito.","effects":{"budget":-2.6,"gathering":1.35,"durationDays":9,"factions":{"comerciantes":-8,"saude":6}}},{"id":"kits","label":"Distribuir kits de proteção sem cancelar os desfiles","outcome":"Os blocos saem. Os kits seguram parte do toque, mas a aglomeração ainda quase dobra a transmissão nos bairros de folia.","lesson":"Proteção individual ajuda uma doença de contato. Ela perde para a densidade se a festa segue intacta.","effects":{"budget":-1.8,"protection":0.15,"gathering":2.1,"durationDays":9,"factions":{"comerciantes":-2,"civil":3}}},{"id":"liberar","label":"Não intervir na folia","outcome":"O comércio comemora. Na orla e no Centro, o contato triplica pelos dias de Carnaval.","lesson":"Omissão também é política pública. O custo aparece em caso, leito e óbito, não no caixa do primeiro dia.","effects":{"gathering":3,"durationDays":9,"factions":{"comerciantes":8,"saude":-6}}}]$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$aniversario-cidade$sdc$, $sdc$Aniversário de Maricá$sdc$, $sdc$Calendário$sdc$, 10, false, $sdc$A programação cívica se concentra entre 23 e 26 de maio. A data da cidade é 26 de maio; em 2026 completam-se 212 anos. Shows e encontro público aumentam o toque numa rede que já pode estar cansada do verão.$sdc$, $sdc$Calendário cultural é calendário epidemiológico quando a via de transmissão é o contato.$sdc$, 5, 5, 23, 26, false, 0, $sdc${"type":"calendar"}$sdc$::jsonb, $sdc$[{"id":"controle","label":"Controlar densidade nos shows e manter a triagem","outcome":"A comemoração acontece com menos aperto. Custa verba e um pouco de paz com quem queria a festa cheia.","lesson":"Dá para manter o rito da cidade e ainda assim baixar a taxa de contato. O desenho da medida importa.","effects":{"budget":-1.8,"gathering":1.25,"durationDays":4,"factions":{"comerciantes":-4,"saude":4}}},{"id":"cheia","label":"Deixar a programação lotada","outcome":"A orla e o Centro recebem a festa cheia. O contato sobe por quatro dias.","lesson":"Uma janela curta de aglomeração basta para recolocar a curva para cima se a prevalência já não é baixa.","effects":{"gathering":2.4,"durationDays":4,"factions":{"comerciantes":5}}}]$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$amparo$sdc$, $sdc$Festa de Nossa Senhora do Amparo$sdc$, $sdc$Calendário$sdc$, 10, false, $sdc$A festa da padroeira, no início de agosto, enche missas e procissão. A vigilância estima maior presença de idosos. É inverno: a mesma rede já atende síndrome respiratória. A Apatia, neles, tende a ocupar mais leito.$sdc$, $sdc$Grupo de risco é quem concentra gravidade, não quem concentra culpa. Triagem existe para achar essas pessoas cedo.$sdc$, 8, 8, 3, 15, false, 0, $sdc${"type":"calendar"}$sdc$::jsonb, $sdc$[{"id":"triagem","label":"Montar triagem dedicada para idosos","outcome":"A festa segue, com ponto de avaliação e prioridade de leito para quem tem mais chance de forma grave.","lesson":"Triagem não interrompe a devoção. Ela impede que a gravidade espere a lotação para ser reconhecida.","effects":{"budget":-1.6,"elderlyRisk":0.1,"durationDays":12,"factions":{"saude":6,"civil":3}}},{"id":"fluxo","label":"Atender no fluxo normal das unidades","outcome":"Não há custo imediato. A circulação de idosos eleva a gravidade enquanto a festa dura.","lesson":"O fluxo normal foi desenhado para um agosto sem duas síndromes ao mesmo tempo. Este agosto não é esse.","effects":{"elderlyRisk":0.7,"durationDays":12}}]$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$temporada$sdc$, $sdc$Natal e Réveillon na orla$sdc$, $sdc$Calendário$sdc$, 10, false, $sdc$A temporada de fim de ano traz visitantes pela RJ-106 para a orla, o Natal iluminado e o Réveillon. Cada entrada noturna pode semear um foco novo em Inoã, Itaipuaçu e Ponta Negra. Fechar a temporada segura o contato e aperta o comércio.$sdc$, $sdc$Importação de casos é um fluxo. Sem medida de entrada, o município trata o que a estrada entrega todo dia.$sdc$, 12, 12, 20, 31, false, 0, $sdc${"type":"calendar"}$sdc$::jsonb, $sdc$[{"id":"lockdown","label":"Restringir a temporada e a entrada noturna","outcome":"Menos visitantes, menos focos novos, mais pressão do comércio da orla.","lesson":"Lockdown turístico é uma barreira de fluxo. O preço político aparece no mesmo dia; o ganho sanitário aparece na semana seguinte.","effects":{"budget":-1.6,"tourism":-0.9,"durationDays":12,"factions":{"comerciantes":-10,"saude":4}}},{"id":"abrir","label":"Manter a temporada aberta","outcome":"O caixa do comércio agradece. Novos focos entram pela rodovia e se instalam na orla.","lesson":"Receita de uma semana de temporada pode custar leitos de janeiro. O jogo só deixa esse atraso visível.","effects":{"infect":{"inoa":40,"itaipuacu":55,"ponta-negra":35},"tourism":0.35,"durationDays":12,"factions":{"comerciantes":7,"saude":-5}}}]$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$dengue-verao$sdc$, $sdc$Onda de dengue e chikungunya$sdc$, $sdc$Arboviroses$sdc$, 12, false, $sdc$As chuvas de verão ampliam o Aedes aegypti. Dengue e chikungunya não passam pelo toque, mas chegam às mesmas UPAs e às mesmas Clínicas da Família. A Apatia continua. A rede é que encolhe.$sdc$, $sdc$Doenças com vias diferentes competem pelo mesmo recurso. Capacidade hospitalar é um bem único.$sdc$, 2, 3, 18, 28, false, 0, $sdc${"type":"calendar"}$sdc$::jsonb, $sdc$[{"id":"mutirao","label":"Desviar verba para vigilância do vetor e hidratação","outcome":"Parte dos leitos de arbovirose é devolvida à rede. A Apatia não muda de via por causa disso.","lesson":"Controlar o Aedes no verão é o que impede a dengue de decidir quem com Apatia fica sem leito.","effects":{"budget":-2.2,"surgeBeds":-16,"durationDays":18,"factions":{"saude":4}}},{"id":"absorver","label":"Absorver a onda na rede já existente","outcome":"Nenhuma equipe sai para o vetor. Os leitos enchem de síndromes que não são a Apatia.","lesson":"Ignorar a co-circulação trata a epidemia nova como se ela fosse a única cliente do hospital.","effects":{"surgeBeds":30,"durationDays":18,"factions":{"saude":-6}}}]$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$srag-inverno$sdc$, $sdc$SRAG de inverno$sdc$, $sdc$Respiratórias$sdc$, 12, false, $sdc$Junho e julho sobem as internações por síndrome respiratória aguda grave. Influenza, metapneumovírus humano e outros vírus respiratórios entram nesse grupo. Nenhum deles é a Apatia. Todos usam oxigênio, leito e a mesma equipe.$sdc$, $sdc$Sazonalidade não espera a doença nova terminar. O inverno chega com a rede no estado em que o verão a deixou.$sdc$, 6, 7, 10, 25, false, 0, $sdc${"type":"calendar"}$sdc$::jsonb, $sdc$[{"id":"retaguarda","label":"Abrir retaguarda respiratória","outcome":"A verba vira leito de campanha e a pressão da SRAG não toma a rede inteira.","lesson":"Plano de contingência sazonal é decisão de antes do pico, não heroísmo no corredor lotado.","effects":{"budget":-2.4,"capacity":20,"surgeBeds":8,"durationDays":20}},{"id":"ordinaria","label":"Manter a escala ordinária","outcome":"A SRAG ocupa uma fatia grande dos leitos por três semanas.","lesson":"Escala ordinária é o nome administrativo da falta de plano.","effects":{"surgeBeds":34,"durationDays":21,"factions":{"saude":-8}}}]$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$sarampo-inoa$sdc$, $sdc$Sarampo nas escolas de Inoã$sdc$, $sdc$Doenças preveníveis$sdc$, 14, false, $sdc$Professores de Inoã notificam casos suspeitos de sarampo. A via é respiratória, não o toque da Apatia. Com cobertura de rotina longe dos cerca de 95% que a imunidade coletiva do sarampo pede, a escola vira amplificador e a atenção básica divide o turno.$sdc$, $sdc$Sarampo tem R0 muito alto. A ferramenta principal é vacina de bloqueio, não só o cartaz. Fechar aula ajuda; não substitui a dose.$sdc$, NULL, NULL, NULL, NULL, false, 0, $sdc${"type":"all","all":[{"type":"metric","metric":"day","op":"gt","value":6},{"type":"metric","metric":"vaccine","op":"lt","value":86}]}$sdc$::jsonb, $sdc$[{"id":"bloqueio","label":"Bloqueio vacinal e suspensão curta das aulas em Inoã","outcome":"A cobertura sobe e o contato escolar cai por alguns dias. Custa caro e irrita famílias.","lesson":"Bloqueio vacinal cerca o caso com imunidade. A aula suspensa só ganha tempo para essa cerca existir.","effects":{"budget":-3,"vaccine":14,"schoolClosure":1,"durationDays":10,"factions":{"civil":-3,"saude":5}}},{"id":"aviso","label":"Nota às famílias, sem bloqueio","outcome":"Algumas famílias procuram a unidade. A cobertura quase não muda e Inoã ganha uma leva de casos.","lesson":"Comunicação sem insumo vira conselho. Sarampo não recua com conselho.","effects":{"budget":-0.6,"vaccine":2,"infect":{"inoa":70}}},{"id":"ignorar","label":"Tratar como boato e seguir só com a Apatia","outcome":"O surto escolar cresce. A população perde confiança e a cobertura de rotina cai mais um pouco.","lesson":"Chamar de boato um caso prevenível não protege a rede. Só atrasa a resposta até o corredor lotar.","effects":{"infect":{"inoa":180},"vaccine":-4,"factions":{"civil":-8,"saude":-4}}}]$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$alerta-polio$sdc$, $sdc$Alerta de risco de poliovírus$sdc$, $sdc$Doenças preveníveis$sdc$, 15, false, $sdc$A cobertura caiu o bastante para a vigilância emitir alerta. Não há surto confirmado de poliomielite. O Brasil é área livre; o vírus ainda circula no mundo. O alerta pergunta se a porta de reintrodução está aberta. A Apatia continua sem vacina. A pólio não.$sdc$, $sdc$Eliminação local não é erradicação global. Cobertura baixa reabre uma doença que o país já tirou de circulação.$sdc$, NULL, NULL, NULL, NULL, false, 0, $sdc${"type":"all","all":[{"type":"metric","metric":"day","op":"gt","value":12},{"type":"metric","metric":"vaccine","op":"lt","value":72}]}$sdc$::jsonb, $sdc$[{"id":"resgate","label":"Campanha de resgate da cobertura","outcome":"A busca ativa sobe a cobertura. O alerta não vira caso. A verba da cura sente o desvio.","lesson":"Resgatar não vacinado é mais barato do que explicar um caso de paralisia que a vacina já sabia evitar.","effects":{"budget":-2.4,"vaccine":12,"factions":{"saude":4,"civil":2}}},{"id":"nota","label":"Publicar uma nota tímida","outcome":"A nota existe. A cobertura quase não se mexe. O risco permanece escrito no boletim.","lesson":"Nota sem busca ativa tranquiliza quem já estava vacinado.","effects":{"budget":-0.4,"vaccine":2}},{"id":"descartar","label":"Descartar o alerta como exagero","outcome":"Parte da população entende que a vacina de rotina deixou de importar. A cobertura cai e a rede ainda reserva leitos para a investigação.","lesson":"Desmentir um alerta de risco, quando o risco é a cobertura, ensina a cidade a ignorar o próximo.","effects":{"vaccine":-5,"surgeBeds":10,"durationDays":14,"factions":{"civil":-6,"saude":-5}}}]$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$meningite-terminal$sdc$, $sdc$Meningite em terminal de ônibus$sdc$, $sdc$Doenças preveníveis$sdc$, 40, false, $sdc$Um caso de meningite bacteriana em passageiro de terminal. A transmissão é por gotículas e contato próximo, com necessidade de avaliar contactantes. Não é a via da Apatia. Confundir as duas gasta a medida errada nas pessoas erradas.$sdc$, $sdc$Quimioprofilaxia de contactantes é decisão de meningite bacteriana. Kit contra toque não faz esse trabalho.$sdc$, NULL, NULL, NULL, NULL, true, 28, $sdc${"type":"all","all":[{"type":"random","chance":0.07},{"type":"metric","metric":"day","op":"gt","value":15}]}$sdc$::jsonb, $sdc$[{"id":"contactantes","label":"Investigar contactantes e fazer profilaxia","outcome":"O foco é cercado. Custa verba e algumas horas da vigilância que também olha a Apatia.","lesson":"Contactante é definição epidemiológica, não um sinônimo de todo mundo que passou na cidade.","effects":{"budget":-1.8,"factions":{"saude":3}}},{"id":"seguir","label":"Registrar e não buscar contactantes","outcome":"O caso entra na estatística. Há óbitos e medo desproporcional no transporte.","lesson":"Subnotificar a resposta de um caso grave ensina o público a tratar todo boletim como rumor.","effects":{"deaths":4,"factions":{"civil":-7}}}]$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$greve-saude$sdc$, $sdc$Colapso das equipes$sdc$, $sdc$Facções$sdc$, 5, false, $sdc$Profissionais das UPAs e das Clínicas da Família cruzam o limite. Escala furada, corredor lotado e adicional atrasado. Se a categoria parar, a capacidade instalada continua no papel e some na prática.$sdc$, $sdc$Leito sem equipe é mobília. A greve, neste jogo, é o que acontece quando a mobília é confundida com cuidado.$sdc$, NULL, NULL, NULL, NULL, true, 18, $sdc${"type":"metric","metric":"faction.saude","op":"lt","value":36}$sdc$::jsonb, $sdc$[{"id":"acordo","label":"Pagar adicional e repor escala","outcome":"A categoria recua do limite. A verba do dia fica curta para pesquisa e comércio.","lesson":"Acordo trabalhista em epidemia é medida sanitária. Sem gente, o protocolo não se aplica sozinho.","effects":{"budget":-2.8,"factions":{"saude":22}}},{"id":"promessa","label":"Prometer solução sem desembolsar","outcome":"O comunicado sai. O apoio quase não muda e a rede segue exposta.","lesson":"Promessa não entra na escala do plantão seguinte.","effects":{"factions":{"saude":4,"civil":-2}}},{"id":"reprimir","label":"Tratar a paralisação como desobediência","outcome":"Parte da equipe sai de fato. A capacidade efetiva cai por duas semanas.","lesson":"Punição não cria profissional. Ela reduz ainda mais a capacidade que já faltava.","effects":{"capacity":-24,"durationDays":14,"factions":{"saude":-12,"civil":-6}}}]$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$revolta-comerciantes$sdc$, $sdc$O comércio abre por conta própria$sdc$, $sdc$Facções$sdc$, 6, false, $sdc$Lojistas e barraqueiros descumprem a restrição. A queixa é objetiva: a quarentena cortou a renda e ninguém compensou. Com a porta aberta, a medida sanitária existe no decreto e não existe na rua.$sdc$, $sdc$Adesão é componente da eficácia. Uma quarentena que o comércio não consegue cumprir é uma quarentena menor do que a escrita.$sdc$, NULL, NULL, NULL, NULL, true, 16, $sdc${"type":"all","all":[{"type":"metric","metric":"faction.comerciantes","op":"lt","value":34},{"type":"metric","metric":"quarantine","op":"gt","value":0.35}]}$sdc$::jsonb, $sdc$[{"id":"compensar","label":"Compensar o comércio e manter a restrição","outcome":"Sai auxílio. A adesão volta e a circulação continua contida.","lesson":"Compensação é o preço de manter o comportamento que a curva exige.","effects":{"budget":-2.2,"factions":{"comerciantes":18}}},{"id":"afrouxar","label":"Suspender a quarentena","outcome":"As portas abrem com autorização. O comércio respira e o contato volta.","lesson":"Afrouxar sem baixar a prevalência devolve a cidade ao ritmo que gerou a restrição.","effects":{"cancelPolicies":["quarentena-parcial","quarentena-rigida"],"factions":{"comerciantes":14,"saude":-4}}},{"id":"firme","label":"Manter o decreto e não pagar ninguém","outcome":"O decreto continua. O cumprimento não. A revolta reduz a adesão por muitos dias.","lesson":"Insistir num papel que a rua já rasgou não preserva a medida. Só preserva a frase.","effects":{"mobility":0.18,"durationDays":10,"factions":{"comerciantes":-10,"civil":-4}}}]$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$panico-obitos$sdc$, $sdc$Pânico depois dos óbitos$sdc$, $sdc$Facções$sdc$, 7, false, $sdc$Um dia com muitos óbitos espalha áudio e fila em porta de unidade. Parte da cidade quer fechar tudo. Outra parte diz que a Apatia não existe. Os dois grupos se aglomeram para discutir.$sdc$, $sdc$Medo sem canal oficial vira aglomeração. Aglomeração, numa doença de toque, vira caso.$sdc$, NULL, NULL, NULL, NULL, true, 14, $sdc${"type":"metric","metric":"deathsToday","op":"gt","value":6}$sdc$::jsonb, $sdc$[{"id":"coletiva","label":"Coletiva diária com os números da rede","outcome":"O número feio é dito por quem cuida da rede. O pânico não zera, mas a rua esvazia um pouco.","lesson":"Transparência não é otimismo. É publicar o número que a pessoa já vai ouvir, só que com contexto.","effects":{"budget":-0.8,"factions":{"civil":12,"saude":3}}},{"id":"silencio","label":"Evitar entrevista para não alarmar","outcome":"O vazio é preenchido por áudio. A confiança cai e o contato sobe.","lesson":"Silêncio oficial não impede o alarme. Ele escolhe quem faz o alarme.","effects":{"factions":{"civil":-10},"mobility":0.12,"durationDays":6}}]$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$revolta-passaporte$sdc$, $sdc$Resistência ao passaporte sanitário$sdc$, $sdc$Facções$sdc$, 8, false, $sdc$O passaporte sanitário condicionou o acesso a lugares lotados. Grupos contrários à vacinação e moradores sem informação clara tratam a regra como castigo. Há protesto na porta dos espaços públicos — de novo, contato.$sdc$, $sdc$Hesitação vacinal cresce quando a regra chega antes da explicação. A Apatia nem tem vacina: o passaporte, aqui, regula circulação, e mesmo assim é lido como imposição sanitária genérica.$sdc$, NULL, NULL, NULL, NULL, true, 16, $sdc${"type":"all","all":[{"type":"metric","metric":"passport","op":"gt","value":0.5},{"type":"metric","metric":"faction.civil","op":"lt","value":42}]}$sdc$::jsonb, $sdc$[{"id":"dialogo","label":"Abrir diálogo e explicar o que a regra faz e não faz","outcome":"A regra permanece, com canal de dúvida. A resistência cai sem revogar o controle de densidade.","lesson":"Explicar o que a medida não faz evita que ela seja culpada pela doença errada.","effects":{"budget":-1,"factions":{"civil":14}}},{"id":"revogar","label":"Revogar o passaporte","outcome":"O protesto dispersa. O controle de acesso aos lugares lotados também.","lesson":"Revogar acalma a rua no dia. A densidade que a regra segurava volta no dia seguinte.","effects":{"cancelPolicies":["passaporte-sanitario"],"factions":{"civil":10,"saude":-3}}},{"id":"endurecer","label":"Endurecer a fiscalização sem novo diálogo","outcome":"A multa aumenta e a cooperação cai. O ganho sanitário da regra encolhe com a fraude e o confronto.","lesson":"Fiscalização sem legitimidade produz evasão. A pessoa deixa de aparecer, não passa a cumprir.","effects":{"factions":{"civil":-12},"mobility":0.1,"durationDays":8}}]$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$desinformacao$sdc$, $sdc$Onda de desinformação$sdc$, $sdc$Infodemia$sdc$, 50, false, $sdc$Circula a versão de que a vacina de rotina causa a Apatia, de que a Apatia é dengue e de que leito vazio é prova de fraude. As três frases empurram famílias para fora da cobertura e para dentro do corredor.$sdc$, $sdc$Infodemia é o excesso de conteúdo falso no meio da resposta. Ela não transmite a Apatia; ela derruba a ferramenta das outras doenças.$sdc$, NULL, NULL, NULL, NULL, true, 18, $sdc${"type":"all","all":[{"type":"random","chance":0.08},{"type":"metric","metric":"day","op":"gt","value":8}]}$sdc$::jsonb, $sdc$[{"id":"frente","label":"Montar uma frente de comunicação com a rede","outcome":"Profissionais respondem às três frases com a via de transmissão certa. A cobertura de rotina se recupera um pouco.","lesson":"Desmentido funciona quando vem de quem a pessoa já encontra na unidade, não só de um cartaz.","effects":{"budget":-1.3,"vaccine":4,"factions":{"civil":10}}},{"id":"ignorar-redes","label":"Não gastar verba com rede social","outcome":"As frases seguem. A cobertura cai e a confiança civil também.","lesson":"Não responder também ensina. Ensina a versão que sobrou sozinha.","effects":{"vaccine":-4,"factions":{"civil":-8}}}]$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$nova-variante$sdc$, $sdc$Nova variante$sdc$, $sdc$Vigilância$sdc$, 45, false, $sdc$O laboratório descreve uma linhagem da Apatia com maior adesão à pele. É a mesma doença fictícia, com taxa de contato mais alta. O nome deste boletim pode ser trocado no painel docente, sem mexer no código.$sdc$, $sdc$Variante muda parâmetro. A vigilância serve para perceber a mudança antes de a curva já ter mudado sozinha.$sdc$, NULL, NULL, NULL, NULL, true, 30, $sdc${"type":"all","all":[{"type":"random","chance":0.06},{"type":"metric","metric":"day","op":"gt","value":18}]}$sdc$::jsonb, $sdc$[{"id":"sequenciar","label":"Acelerar o sequenciamento e ajustar a orientação","outcome":"A pesquisa ganha um salto e a linhagem circula com um aumento menor de contato, porque a orientação muda a tempo.","lesson":"Sequenciar não é vaidade de laboratório. É o que diz se o beta de ontem ainda serve.","effects":{"budget":-2,"research":6,"betaAdd":0.04,"durationDays":12}},{"id":"observar-linhagem","label":"Observar sem mudar a resposta","outcome":"A linhagem se espalha com a taxa nova por duas semanas, no escuro.","lesson":"Esperar a curva confirmar o laboratório é chegar atrasado de propósito.","effects":{"betaAdd":0.1,"durationDays":14,"factions":{"saude":-3}}}]$sdc$::jsonb);
INSERT INTO events (id, title, category, priority, opening, body, lesson, month_start, month_end, day_start, day_end, repeatable, cooldown, trigger, choices) VALUES ($sdc$rj-106$sdc$, $sdc$Foco novo pela RJ-106$sdc$, $sdc$Fronteiras$sdc$, 55, false, $sdc$A vigilância de fim de noite aponta visitantes sintomáticos descendo na entrada oeste e seguindo para a orla. Inoã é porta. Itaipuaçu e Ponta Negra são destino. Sem barreira, o foco de fora vira caso de dentro até amanhã.$sdc$, $sdc$Bairro de entrada não é bairro culpado. É o lugar onde a medida de fronteira ainda alcança a pessoa.$sdc$, NULL, NULL, NULL, NULL, true, 12, $sdc${"type":"all","all":[{"type":"random","chance":0.1},{"type":"metric","metric":"day","op":"gt","value":5}]}$sdc$::jsonb, $sdc$[{"id":"barreira-noturna","label":"Barreira sanitária noturna na entrada","outcome":"A triagem segura parte dos sintomáticos. O comércio de passagem reclama da fila.","lesson":"Barreira funciona na porta, não depois que a pessoa já circulou o dia inteiro na orla.","effects":{"budget":-1.2,"barriers":0.8,"durationDays":6,"factions":{"comerciantes":-4,"saude":2}}},{"id":"fluxo-livre","label":"Manter o fluxo da rodovia","outcome":"Não há fila. Há casos novos em Inoã, Itaipuaçu e Ponta Negra.","lesson":"Fluxo livre é uma escolha de importação. O município recebe o que não barrou.","effects":{"infect":{"inoa":22,"itaipuacu":18,"ponta-negra":12},"factions":{"comerciantes":3}}}]$sdc$::jsonb);
INSERT INTO lessons (id, title, topic, body) VALUES ($sdc$apatia$sdc$, $sdc$A Apatia é fictícia$sdc$, $sdc$Cenário$sdc$, $sdc$A Apatia não existe fora deste jogo. Ela foi desenhada com uma via só: o toque, o contato físico prolongado. Serve para você ver o efeito de festa, fila, comércio e kit sem confundir com uma doença real. Dengue, sarampo, pólio, meningite e as síndromes respiratórias que aparecem no boletim são reais — e não se transmitem como a Apatia.$sdc$);
INSERT INTO lessons (id, title, topic, body) VALUES ($sdc$isolamento$sdc$, $sdc$Isolamento não é quarentena$sdc$, $sdc$Medidas$sdc$, $sdc$Isolamento separa quem está doente. Quarentena restringe quem foi exposto e ainda pode adoecer. Distanciamento reduz contato na população geral. O jogo chama de quarentena a restrição ampla de circulação, como a gestão municipal acaba fazendo na prática, e mostra o custo: renda, adesão e confiança. Usar a palavra certa ajuda a escolher a medida certa.$sdc$);
INSERT INTO lessons (id, title, topic, body) VALUES ($sdc$imunidade$sdc$, $sdc$Imunidade coletiva$sdc$, $sdc$Vacinas$sdc$, $sdc$Imunidade coletiva é o ponto em que há gente protegida o suficiente para o patógeno não sustentar a cadeia. No sarampo, como o R0 é muito alto, esse ponto fica perto de 95% de cobertura. Abaixo disso, um caso importado encontra suscetível. A Apatia não tem vacina neste cenário. A cobertura que você administra é a de rotina, e ela decide se uma segunda doença entra na mesma rede.$sdc$);
INSERT INTO lessons (id, title, topic, body) VALUES ($sdc$erradicacao$sdc$, $sdc$Eliminação não é erradicação$sdc$, $sdc$Vacinas$sdc$, $sdc$Eliminação significa interromper a circulação numa região. Erradicação significa acabar com o patógeno no mundo. A poliomielite foi eliminada no Brasil; não foi erradicada no planeta. Por isso uma cobertura baixa não é um detalhe histórico. É uma porta de reintrodução. O alerta do jogo não afirma um surto. Ele afirma o risco.$sdc$);
INSERT INTO lessons (id, title, topic, body) VALUES ($sdc$capacidade$sdc$, $sdc$A letalidade também é da rede$sdc$, $sdc$Hospitais$sdc$, $sdc$Quando há leito e equipe, parte dos graves sobrevive. Quando a ocupação passa de 100%, o excedente é tratado tarde ou não é tratado. A mesma doença mata mais. Arbovirose no verão e SRAG no inverno não precisam ser a Apatia para produzir esse excesso: basta ocuparem o leito que faltou. Os 180 leitos iniciais são uma abstração didática, não o inventário real das unidades de Maricá.$sdc$);
INSERT INTO lessons (id, title, topic, body) VALUES ($sdc$vias$sdc$, $sdc$Três vias, a mesma rede$sdc$, $sdc$Transmissão$sdc$, $sdc$Toque, gotícula, mosquito e vírus respiratório não respondem à mesma medida. Kit e densidade seguram contato. Vacina segura sarampo e pólio. Controle do Aedes segura dengue e chikungunya. O que é comum é o destino: UPA, Clínica da Família, oxigênio, profissional. Uma crise educacional deste jogo é perceber que a medida errada gasta a verba da medida certa.$sdc$);
INSERT INTO lessons (id, title, topic, body) VALUES ($sdc$infodemia$sdc$, $sdc$Infodemia e hesitação$sdc$, $sdc$Confiança$sdc$, $sdc$Infodemia é o volume de informação falsa ou desencontrada que atrapalha a resposta. Hesitação vacinal não se desfaz com multa como primeira ferramenta. Passaporte, decreto e fila precisam de uma frase clara sobre o que a regra faz. Sem essa frase, grupos diferentes se juntam no protesto — e o protesto, numa doença de toque, é mais contato.$sdc$);
INSERT INTO lessons (id, title, topic, body) VALUES ($sdc$maricá$sdc$, $sdc$O recorte de Maricá$sdc$, $sdc$Território$sdc$, $sdc$O município tem quatro distritos oficiais: Sede, Ponta Negra, Inoã e Itaipuaçu. O mapa da sala é uma placa esquemática com oito recortes jogáveis, não o limite oficial de cada bairro. A soma das populações reproduz a estimativa do IBGE para 2026, 212.703 pessoas. O Censo de 2022 contou 197.277. A RJ-106 aparece como porta de entrada porque é por ela que o fluxo regional chega.$sdc$);
INSERT INTO tips (id, text, trigger) VALUES ($sdc$dica-leito$sdc$, $sdc$A ocupação passou de 75%. Leito novo custa menos do que a letalidade de quem ficou sem vaga.$sdc$, $sdc${"type":"metric","metric":"occupancy","op":"gt","value":0.75}$sdc$::jsonb);
INSERT INTO tips (id, text, trigger) VALUES ($sdc$dica-pesquisa$sdc$, $sdc$A cura não anda sozinha. A pesquisa básica é lenta; a intensiva cabe mal junto com uma quarentena rígida.$sdc$, $sdc${"type":"all","all":[{"type":"metric","metric":"research","op":"lt","value":35},{"type":"metric","metric":"day","op":"gt","value":6}]}$sdc$::jsonb);
INSERT INTO tips (id, text, trigger) VALUES ($sdc$dica-vacina$sdc$, $sdc$A Apatia não tem vacina. Sarampo e pólio têm. Cobertura baixa abre uma segunda crise na mesma equipe.$sdc$, $sdc${"type":"metric","metric":"vaccine","op":"lt","value":75}$sdc$::jsonb);
INSERT INTO tips (id, text, trigger) VALUES ($sdc$dica-comercio$sdc$, $sdc$A quarentena está irritando o comércio. Sem compensação, a porta abre e a medida perde força.$sdc$, $sdc${"type":"all","all":[{"type":"metric","metric":"faction.comerciantes","op":"lt","value":48},{"type":"metric","metric":"quarantine","op":"gt","value":0.3}]}$sdc$::jsonb);
INSERT INTO tips (id, text, trigger) VALUES ($sdc$dica-saude$sdc$, $sdc$As equipes estão no limite. Adicional e contratação seguram gente; decreto não cobre plantão.$sdc$, $sdc${"type":"metric","metric":"faction.saude","op":"lt","value":48}$sdc$::jsonb);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$beta$sdc$, 0.27, $sdc$Taxa de contato da Apatia$sdc$, $sdc$Força de infecção diária quando o fator de circulação é 1. A Apatia passa por toque.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$recovery$sdc$, 0.11, $sdc$Recuperação diária$sdc$, $sdc$Fração dos infectados que deixa de transmitir a cada dia.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$severeRate$sdc$, 0.055, $sdc$Taxa de gravidade$sdc$, $sdc$Fração dos infectados que precisa de leito.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$elderlySevere$sdc$, 0.85, $sdc$Peso da idade na gravidade$sdc$, $sdc$Quanto a proporção de idosos do bairro aumenta a necessidade de leito.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$baseLethality$sdc$, 0.012, $sdc$Letalidade dos tratados$sdc$, $sdc$Óbitos por dia entre doentes da Apatia que conseguiram leito.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$overloadLethality$sdc$, 0.07, $sdc$Letalidade sem leito$sdc$, $sdc$Óbitos por dia entre quem ficou fora da capacidade.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$baseIncome$sdc$, 5, $sdc$Receita diária$sdc$, $sdc$Entrada do fundo emergencial em milhões de reais fictícios, sem restrição de circulação.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$quarantineWeight$sdc$, 0.5, $sdc$Perda de receita na quarentena$sdc$, $sdc$Peso da quarentena na fórmula da receita.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$researchBase$sdc$, 0.25, $sdc$Pesquisa espontânea$sdc$, $sdc$Avanço diário da cura sem investimento dedicado, em pontos percentuais.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$importRate$sdc$, 0.028, $sdc$Importação entre bairros$sdc$, $sdc$Quanto a prevalência de um vizinho empurra casos novos.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$startBudget$sdc$, 26, $sdc$Verba inicial$sdc$, $sdc$Milhões fictícios disponíveis no primeiro dia.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$startCapacity$sdc$, 180, $sdc$Leitos iniciais$sdc$, $sdc$Abstração didática da rede. Não é o censo real de leitos de Maricá.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$startVaccine$sdc$, 62, $sdc$Cobertura vacinal inicial$sdc$, $sdc$Cobertura de rotina, em percentual. Não protege contra a Apatia; evita surtos paralelos.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$arbovirusBeds$sdc$, 24, $sdc$Leitos de arbovirose$sdc$, $sdc$Leitos ocupados por dengue e chikungunya nos meses de verão.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$arbovirusMask$sdc$, 2063, $sdc$Meses de arbovirose$sdc$, $sdc$Máscara de bits: jan=1, fev=2, mar=4, abr=8, mai=16, jun=32, jul=64, ago=128, set=256, out=512, nov=1024, dez=2048. 2063 = jan a abr + dez.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$sragBeds$sdc$, 28, $sdc$Leitos de SRAG$sdc$, $sdc$Pressão respiratória de inverno, independente da Apatia.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$sragMask$sdc$, 224, $sdc$Meses de SRAG$sdc$, $sdc$224 = junho + julho + agosto.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$overloadDays$sdc$, 6, $sdc$Dias de colapso da rede$sdc$, $sdc$Dias seguidos acima de 100% da capacidade até a derrota.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$disorderThreshold$sdc$, 22, $sdc$Ordem crítica$sdc$, $sdc$Abaixo deste valor a ordem pública entra em colapso progressivo.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$disorderDays$sdc$, 4, $sdc$Dias de desordem$sdc$, $sdc$Dias seguidos com ordem crítica até a derrota.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$deathCollapseRatio$sdc$, 0.045, $sdc$Teto de óbitos$sdc$, $sdc$Fração da população em óbitos que encerra a partida.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$strikeThreshold$sdc$, 28, $sdc$Limiar de greve$sdc$, $sdc$Apoio dos profissionais de saúde abaixo disto reduz a capacidade efetiva.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$strikeCapacityMult$sdc$, 0.72, $sdc$Capacidade durante a greve$sdc$, $sdc$Multiplicador dos leitos quando a equipe cruza o limiar de greve.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$revoltThreshold$sdc$, 30, $sdc$Limiar de revolta do comércio$sdc$, $sdc$Abaixo disto a quarentena perde adesão.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$revoltLeak$sdc$, 0.55, $sdc$Adesão restante na revolta$sdc$, $sdc$Fração da quarentena que ainda funciona quando o comércio abre por conta própria.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$panicThreshold$sdc$, 28, $sdc$Limiar de pânico$sdc$, $sdc$Apoio civil abaixo disto aumenta aglomerações e a transmissão por toque.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$panicBeta$sdc$, 1.22, $sdc$Transmissão no pânico$sdc$, $sdc$Multiplicador da circulação quando a população entra em pânico.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$healthOverloadDaily$sdc$, 6, $sdc$Desgaste da saúde na superlotação$sdc$, $sdc$Queda diária do apoio da categoria com ocupação acima de 100%.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$healthPressureDaily$sdc$, 3.2, $sdc$Desgaste da saúde sob pressão$sdc$, $sdc$Queda diária quando a ocupação passa de 85%.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$healthRecoverDaily$sdc$, 1.3, $sdc$Recuperação da saúde$sdc$, $sdc$Ganho diário do apoio da categoria quando a rede respira.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$commerceRecoverDaily$sdc$, 1.4, $sdc$Recuperação do comércio$sdc$, $sdc$Ganho diário dos comerciantes quando não há quarentena relevante.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$civilDeathWeight$sdc$, 0.42, $sdc$Pânico por óbito$sdc$, $sdc$Queda do apoio civil por óbito do dia.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$civilRecoverDaily$sdc$, 0.45, $sdc$Recuperação civil$sdc$, $sdc$Ganho diário pequeno de confiança, antes dos outros efeitos.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$quarantineBetaCut$sdc$, 0.85, $sdc$Corte de contato na quarentena$sdc$, $sdc$Quanto cada ponto de quarentena reduz o fator de transmissão.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$schoolCut$sdc$, 0.72, $sdc$Corte nas escolas fechadas$sdc$, $sdc$Multiplicador da transmissão em bairros escolares com aulas suspensas.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$barrierCut$sdc$, 0.55, $sdc$Corte nas barreiras$sdc$, $sdc$Redução da transmissão em bairros de entrada quando há barreira.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$schoolMin$sdc$, 0.45, $sdc$Bairro escolar$sdc$, $sdc$A partir desta marca o fechamento de escolas afeta o bairro.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$borderMin$sdc$, 0.35, $sdc$Bairro de entrada$sdc$, $sdc$A partir desta marca a barreira rodoviária afeta o bairro.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$scorePerDay$sdc$, 15, $sdc$Pontos por dia$sdc$, $sdc$Peso dos dias sobrevividos na pontuação.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$scorePerResearch$sdc$, 2, $sdc$Pontos por pesquisa$sdc$, $sdc$Peso do progresso da cura na pontuação.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$scoreWin$sdc$, 300, $sdc$Bônus da cura$sdc$, $sdc$Pontos extras se a pesquisa chegar a 100%.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$scorePerDeath$sdc$, 0.02, $sdc$Penalidade por óbito$sdc$, $sdc$Pontos retirados por óbito.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$protectionCap$sdc$, 0.8, $sdc$Teto dos kits$sdc$, $sdc$Proteção máxima somada contra o toque.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$gatheringMinTourism$sdc$, 0.45, $sdc$Turismo que sente a folia$sdc$, $sdc$Bairros com turismo acima disto recebem o multiplicador cheio de aglomeração.$sdc$);
INSERT INTO parameters (key, value, label, hint) VALUES ($sdc$gatheringMinCommerce$sdc$, 0.75, $sdc$Comércio que sente a folia$sdc$, $sdc$Bairros comerciais acima disto também recebem a aglomeração cheia.$sdc$);
INSERT INTO formulas (id, label, expression, explanation) VALUES ($sdc$force$sdc$, $sdc$Força de infecção$sdc$, $sdc$infectedShare * beta * factor + imported$sdc$, $sdc$infectedShare é a prevalência local. beta é a taxa de contato da Apatia. factor reúne kits, quarentena, escolas, barreiras, turismo e aglomeração. imported vem dos bairros vizinhos.$sdc$);
INSERT INTO formulas (id, label, expression, explanation) VALUES ($sdc$newInfections$sdc$, $sdc$Casos novos$sdc$, $sdc$susceptible * (1 - exp(-1 * force))$sdc$, $sdc$Modelo discreto de força de infecção. O resultado é limitado aos suscetíveis do bairro. Editar esta expressão muda o cálculo de dano do contágio sem alterar o código.$sdc$);
INSERT INTO formulas (id, label, expression, explanation) VALUES ($sdc$deaths$sdc$, $sdc$Óbitos do dia$sdc$, $sdc$treated * max(0, baseLethality + lethalityShift) + untreated * overloadLethality$sdc$, $sdc$treated são doentes da Apatia que conseguiram leito. untreated é o excesso total da rede, incluindo leitos tomados por outras síndromes. É o cálculo de dano hospitalar.$sdc$);
INSERT INTO formulas (id, label, expression, explanation) VALUES ($sdc$income$sdc$, $sdc$Receita do dia$sdc$, $sdc$baseIncome * (1 - quarantineWeight * quarantine) + incomeExtra$sdc$, $sdc$A quarentena reduz a arrecadação do fundo emergencial. incomeExtra soma bônus e penalidades das medidas ativas.$sdc$);
INSERT INTO formulas (id, label, expression, explanation) VALUES ($sdc$research$sdc$, $sdc$Avanço da cura$sdc$, $sdc$researchBase + researchDaily$sdc$, $sdc$Pontos percentuais acrescentados à pesquisa no fim do dia. researchDaily vem das políticas de pesquisa ativas.$sdc$);
INSERT INTO formulas (id, label, expression, explanation) VALUES ($sdc$occupancy$sdc$, $sdc$Ocupação hospitalar$sdc$, $sdc$(apatiaBeds + parallelBeds) / capacity$sdc$, $sdc$Soma quem precisa de leito por causa da Apatia e quem já ocupa leito por arbovirose ou SRAG, dividida pela capacidade efetiva.$sdc$);
INSERT INTO formulas (id, label, expression, explanation) VALUES ($sdc$score$sdc$, $sdc$Pontuação final$sdc$, $sdc$days * scorePerDay + research * scorePerResearch + winBonus - dead * scorePerDeath$sdc$, $sdc$O placar ordena primeiro pelos dias sobrevividos. Esta pontuação aparece como critério de desempate e como leitura do custo humano.$sdc$);
